SELECT web_id webId, SUM(c2s_byte_len + s2c_byte_len) count FROM traffic_http_statistic t where stat_time>= #{statTime} and stat_time< #{endTime}
and web_id in
#{singleType}
group by t.web_id

	SELECT SUM(c2s_byte_len+s2c_byte_len) count FROM
	traffic_http_statistic t
	where
 stat_time>= #{statTime} and stat_time< #{endTime} 
	
		and t.web_id not in
		
			#{singleType}

select 	web_id webId, max(unique_num) uniqueNum,entrance_id entranceId,SUM(c2s_byte_len + s2c_byte_len) byteCount,
sum(c2s_pkt_num + s2c_pkt_num) pktCount from traffic_http_focus_statistic t where
 stat_time>= #{beginDate} and stat_time< #{endDate}

	and web_id=#{domain}


	and entrance_id=#{entranceId}

group by web_id order by unique_num

select 	stat_time time, max(unique_num)count from traffic_http_focus_statistic t where
 stat_time>= #{beginDate} and stat_time< #{endDate}
	and web_id=#{domain}

	and entrance_id=#{entranceId}


group by stat_time
 order by stat_time
